#!/usr/bin/env python3
"""Corner numbers and marshal-sector flags on the replay map.
Exporter: reads circuit_corners and circuit_marshal_sectors from the lake and writes "corners" and "marshal" into each replay file.
Page: draws corner numbers (with a toggle) and highlights a marshal sector while a yellow or double yellow is out in it.
Run from the repository root:  python3 install_corners.py
Refuses, changing nothing, if any anchor is not found exactly once or the change is already there.
After it, re-export the replays (see the printed steps): old replay files simply have no corners or flags."""
import sys
from pathlib import Path

