APPEND_TS = '\n\n\n// ---- marshal-sector flags ----\n\nexport type SectorFlag = "yellow" | "double";\n\n// The sectors that have a yellow flag out at time t, read from the race-control messages ("YELLOW IN TRACK SECTOR 7",\n// "DOUBLE YELLOW IN TRACK SECTOR 7", "CLEAR IN TRACK SECTOR 7"). A flag stays until its own clear message.\nexport function sectorFlagsAt(file: ReplayFile, t: number): Map<number, SectorFlag> {\n  const out = new Map<number, SectorFlag>();\n  for (const m of file.messages) {\n    if (m[0] > t) break;\n    const hit = /^\\s*(DOUBLE YELLOW|YELLOW|CLEAR) IN TRACK SECTOR\\s+(\\d+)/i.exec(m[4] ?? "");\n    if (!hit) continue;\n    const n = Number(hit[2]);\n    const what = hit[1].toUpperCase();\n    if (what === "CLEAR") out.delete(n);\n    else out.set(n, what === "DOUBLE YELLOW" ? "double" : "yellow");\n  }\n  return out;\n}\n\n// The outline points of marshal sector n: from its post to the next sector\'s post (wrapping round the lap). Null if unknown.\nexport function sectorPoints(file: ReplayFile, n: number): [number, number][] | null {\n  const posts = file.marshal;\n  if (!posts || posts.length < 2) return null;\n  const k = posts.findIndex((m) => m[0] === n);\n  if (k < 0) return null;\n  const pts = file.track.pts;\n  const a = posts[k][3];\n  const b = posts[(k + 1) % posts.length][3];\n  const out: [number, number][] = [];\n  for (let i = a; ; i = (i + 1) % pts.length) {\n    out.push(pts[i]);\n    if (i === b || out.length > pts.length) break;\n  }\n  return out;\n}\n'
CSS = '\n/* ---- upgrade: corner numbers and marshal-sector flags ---- */\n.rp-corner { fill: var(--ink-3); font-size: 15px; font-weight: 600; pointer-events: none; }\n.rp-sector { fill: none; stroke: #f0c455; stroke-width: 26; stroke-linejoin: round; stroke-linecap: butt; opacity: 0.85; }\n.rp-sector-core { fill: none; stroke: rgba(240, 196, 85, 0.35); stroke-width: 16; stroke-linejoin: round; }\n.rp-sector-double { stroke: #ff9f1c; }\n.rp-sector-tag { fill: #f0c455; font-size: 16px; font-weight: 800; paint-order: stroke; stroke: var(--surface); stroke-width: 4px; pointer-events: none; }\n'

root = Path(".")
problems = []
new = {}
for f, edits in EDITS.items():
    pth = root / f
    if not pth.exists():
        problems.append(f + ": not found (run from the repository root)")
        continue
    t = pth.read_text(encoding="utf-8")
    for old, rep in edits:
        n = t.count(old)
        if n != 1:
            problems.append(f"{f}: anchor found {n} times: {old[:90]!r}")
        else:
            t = t.replace(old, rep)
    new[f] = t
for f, extra in (("web/lib/replay.ts", APPEND_TS), ("web/app/replay/replay.css", CSS)):
    pth = root / f
    if not pth.exists():
        problems.append(f + ": not found")
        continue
    t = new.get(f, pth.read_text(encoding="utf-8"))
    if "sectorFlagsAt" in t or "rp-sector" in t:
        problems.append(f + ": already has the marshal-sector code")
    new[f] = t.rstrip("\n") + "\n" + extra
if problems:
    print("REFUSING, nothing changed:")
    print("\n".join("  " + x for x in problems))
    sys.exit(1)
for f, t in new.items():
    (root / f).write_text(t, encoding="utf-8")
